<section id="credit"><h2>Kebijakan kredit global</h2><form id="policyForm"><label>Limit (Rp) <input id="limit" type="number" min="0" max="9999999999.99" step="0.01" required value="{{ $policy?->limit_amount ?? 0 }}"></label><label>Alasan <input id="reason" maxlength="255" required></label><p>Jatuh tempo: 7 hari kalender sejak serah terima.</p><button>Simpan limit</button></form><h3>Fasilitas anggota</h3><div class="scroll"><table><thead><tr><th>Anggota</th><th>Nomor</th><th>Status kredit</th><th>Aksi</th></tr></thead><tbody>@forelse($members as $member)<tr><td>{{ $member->full_name }}</td><td>{{ $member->member_number }}</td><td>{{ $member->creditAccount?->status ?? 'BLOCKED' }}</td><td><button type="button" data-member="{{ $member->id }}" data-status="{{ $member->creditAccount?->status === 'ACTIVE' ? 'BLOCKED' : 'ACTIVE' }}" class="credit-action">{{ $member->creditAccount?->status === 'ACTIVE' ? 'Blokir' : 'Aktifkan' }}</button></td></tr>@empty<tr><td colspan="4">Belum ada anggota.</td></tr>@endforelse</tbody></table></div></section>
