</main><script>
async function patch(url,payload,button){button.disabled=true;try{const r=await fetch(url,{method:'PATCH',credentials:'same-origin',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify(payload)});const data=await r.json();if(!r.ok||!data.success)throw new Error(data.message||'Perubahan ditolak.');sessionStorage.setItem('managerFeedback',data.message);location.reload();}catch(e){document.getElementById('managerFeedback').textContent=e.message;button.disabled=false;}}
document.getElementById('policyForm').addEventListener('submit',e=>{e.preventDefault();patch('/api/v1/credit-policy',{limit_amount:document.getElementById('limit').value,reason:document.getElementById('reason').value},e.submitter);});
document.querySelectorAll('.credit-action').forEach(b=>b.addEventListener('click',()=>{const dialog=document.getElementById('managerConfirm');dialog.returnValue='cancel';dialog.addEventListener('close',()=>{if(dialog.returnValue==='ok')patch('/api/v1/members/'+b.dataset.member+'/credit-status',{status:b.dataset.status},b);},{once:true});dialog.showModal();}));
try { const message=sessionStorage.getItem('managerFeedback'); if(message){document.getElementById('managerFeedback').textContent=message;sessionStorage.removeItem('managerFeedback');} }catch(e){}
</script></body></html>
